(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.3)*20+Math.cos(y*0.012-t*0.2)*15;
  const w1y = Math.cos(y*0.015-t*0.25)*20+Math.sin(x*0.013+t*0.35)*15;
  const w2x = Math.sin((x+w1x)*0.025+t*0.5)*10+Math.cos((y+w1y)*0.02-t*0.4)*8;
  const w2y = Math.cos((y+w1y)*0.025-t*0.45)*10+Math.sin((x+w1x)*0.022+t*0.55)*8;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+4)*40,0.05,2.8]
  ];
  let aS=0,iS=0,res=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    res+=Math.sin(d*f*1.3-t*sp*0.8)*Math.cos(d*f*0.5+t*sp*0.4);
  }
  const act=aS/8,inh=iS/8,resonance=res/8;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=(Math.sin(sx*0.08-sy*0.06+t*1.5)+Math.cos(sx*0.07+sy*0.09-t*1.8))/2*0.5;
  const bg3=Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const sp1=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2=Math.sin(dist*0.08+ang*2-t*2.0)*Math.cos(dist*0.06-ang*5+t*1.8)*0.3;
  const cX=sx*0.08,cY=sy*0.08;
  const cIx=Math.floor(cX),cIy=Math.floor(cY);
  let minD=999,secD=999;
  for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++){
    const nx=cIx+dx,ny=cIy+dy;
    const px=nx+0.5+Math.sin(nx*3.7+ny*2.3+t*0.4)*0.35;
    const py=ny+0.5+Math.cos(nx*2.1+ny*3.9+t*0.35)*0.35;
    const cd=(cX-px)**2+(cY-py)**2;
    if(cd<minD){secD=minD;minD=cd;}else if(cd<secD)secD=cd;
  }
  const cellEdge=Math.sqrt(secD)-Math.sqrt(minD);
  const cell=Math.tanh(cellEdge*4)*0.4;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+sp1+sp2+resonance*0.5)*2.0);
  const rd=Math.tanh(reaction*1.5-cell*0.8+bg*0.2);
  const blend=rd*0.6+reaction*0.25+cell*0.15,v=blend*0.5+0.5;
  const pal=[
    [5,12,45],[8,30,82],[12,62,112],[18,102,132],
    [32,152,142],[82,182,118],[182,192,68],
    [222,162,58],[212,112,62],[172,58,68],
    [102,28,62],[45,14,52],[5,12,45]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.65?1.12:1.0;
  const glow=Math.max(0,1-cellEdge*3)*0.15;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*35)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*55)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*80)|0)
  ];
}
